'use strict';
const $=s=>document.querySelector(s);
const ICONS={horse:'<path d="M5 21c0-5 1-8 5-11L9 3l5 3 4-2-1 5 4 5-2 3-6-1-1 5 M9 6C5 7 3 11 3 16 M14 10h.01 M16 14l3 1"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',stable:'<path d="m3 9 9-6 9 6v12H3zM9 21v-9h6v9M3 9h18M7 7v3m10-3v3"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M2 21v-3a7 7 0 0 1 14 0v3m1-17a3 3 0 0 1 0 6m3 11v-3a7 7 0 0 0-3-6"/>',trail:'<path d="m2 20 7-13 5 8 3-5 5 10zM8 9l2 3 2-1M16 4h5m-3-2v4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',comment:'<path d="M21 11.5a9 9 0 1 1-16.3 5.3L3 22l5.2-1.7A9 9 0 0 0 21 11.5Z"/>',bookmark:'<path d="M5 3h14v19l-7-5-7 5z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>',leaf:'<path d="M20 3C9 1 2 7 5 15c3 8 17 5 15-12ZM4 21 16 8"/>',feed:'<path d="M4 9h16l-2 12H6zm2-4c2 0 2-3 4-3s2 3 4 3 2-3 4-3M3 9h18"/>',brush:'<path d="m9 3 12 12-6 6L3 9zm-3 9-4 4m7-1-4 4m7-1-4 4"/>',check:'<path d="m5 12 4 4L20 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-10 4a5 5 0 0 1 6 0"/><circle cx="12" cy="20" r=".5"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m21 15-5-5L5 21"/>',edit:'<path d="m4 16 12-12 4 4L8 20H4zM14 6l4 4"/>'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24">${ICONS[n]||ICONS.leaf}</svg>`;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const day=()=>new Date(Date.now()+(Cloud?.active?Cloud.clockOffset:0)).toISOString().slice(0,10);
const KEY='meadowgate-v1';
const Cloud=window.MeadowCloud;
let cloudLoading=false,activeCloudUserId=null;
const playerName=()=>Cloud?.active?Cloud.displayName:'Yoshi';
const playerInitials=()=>Cloud?.active?String(Cloud.user.user_metadata?.full_name||playerName()).trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase():'YS';
const progressNote=()=>Cloud?.active?'Account progress saves to Supabase when connected. Offline rewards wait for server verification.':'Demo progress saves on this device. Sign in from Your account to sync a separate stable.';
const seed=()=>({version:1,createdAt:Date.now(),points:120,care:{},rides:{},joined:false,clubs:[],liked:[],saved:[],comments:{},posts:[],journal:[],horses:[{id:'willow',name:'Willow',breed:'American Quarter Horse',color:'Chestnut',baseMonths:72,image:'willow.webp',trait:'The gentle soul',bio:'A curious heart and a soft spot for apple slices. Willow is happiest on a quiet trail with a familiar friend.',bond:68,energy:75,happiness:62},{id:'atlas',name:'Atlas',breed:'Andalusian',color:'Dapple gray',baseMonths:96,image:'atlas.webp',trait:'The old soul',bio:'Steady, thoughtful, and always first to the gate. Atlas makes every new rider feel at home.',bond:81,energy:84,happiness:78},{id:'sunny',name:'Sunny',breed:'Welsh Pony',color:'Palomino',baseMonths:48,image:'sunny.webp',trait:'The little adventurer',bio:'Small hooves, big personality. Sunny can turn a walk around the paddock into an adventure.',bond:54,energy:95,happiness:70}]});
let state,storageOK=true;try{state=JSON.parse(localStorage.getItem(KEY))||seed();if(state.version!==1)state=seed();}catch{state=seed();storageOK=false;}
let worldReturn='stable',worldReturnScroll=0,hasNavigated=false;
let route='home',selected='willow',feedTab='all',query='',offlinePreview=false,cacheStatus='Preparing offline access…',cacheReady=false,deferredInstall=null,platform=/iPhone|iPad|iPod/.test(navigator.userAgent)?'ios':'android',trailSession=null,toastTimer;
const samplePosts=[{id:'mia',name:'Mia Harper',initials:'MH',avatar:'sage',time:'2 hours ago',tag:'LITTLE WINS',title:'A small win for a big heart.',text:'Willow used to stop at every puddle. Today? Straight through, ears forward. Sometimes the smallest steps feel like the biggest ones. 🌿',image:'willow.webp',likes:24,comments:[{name:'Ellie Rose',text:'Those little milestones are the best. Well done, you two!'}]},{id:'ellie',name:'Ellie Rose',initials:'ER',avatar:'clay',time:'4 hours ago',tag:'LET’S TALK',title:'What was your first horse’s name?',text:'Mine was a very opinionated pony called Pepper. I still think about him whenever I see a chestnut. Tell me yours—I love these stories.',likes:18,comments:[{name:'Sam Wilson',text:'Blue! A gray pony with a very misleading name.'}]},{id:'sam',name:'Sam Wilson',initials:'SW',avatar:'lilac',time:'Yesterday',tag:'FROM THE STABLE',title:'A golden kind of afternoon.',text:'No ribbons, no stopwatch. Just Sunny and a long way home. This is the part I missed most.',image:'sunny.webp',likes:31,comments:[]}];
function save(operation){if(Cloud?.active){try{Cloud.stage(operation,state);return true;}catch(error){toast(error.message);return false;}}try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{storageOK=false;toast('Device storage is unavailable. Progress will last until this page closes.');return false;}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
window.TrottToast=toast;
const horse=id=>state.horses.find(h=>h.id===id)||state.horses[0];
function age(h){if(h.bornAt){const m=Math.max(0,Math.floor((Date.now()-h.bornAt)/86400000));return `${Math.floor(m/12)}y ${m%12}m`;}const months=h.baseMonths+Math.max(0,Math.floor((Date.now()+(Cloud?.active?Cloud.clockOffset:0)-state.createdAt)/86400000));return `${Math.floor(months/12)}y ${months%12}m`;}
const careKey=(id,action)=>`${day()}:${id}:${action}`;
const cared=(id,action)=>!!state.care[careKey(id,action)];
const completed=h=>['feed','groom','bond'].filter(a=>cared(h.id,a)).length;
function nav(){const items=[['home','home','Home'],['stable','stable','My stable'],['world','horse','3D world'],['community','people','Community'],['trail','trail','Trail ride'],['offline','download','Install & offline'],['account','people','Your account']];$('#desktop-nav').innerHTML=items.map(([r,i,t])=>`<a href="#${r}" class="nav-link ${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${r==='stable'?'<span class="nav-count">'+state.horses.length+'</span>':''}</a>`).join('');$('#mobile-nav').innerHTML=items.filter(x=>!['offline','account'].includes(x[0])).map(([r,i,t])=>`<a href="#${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(i)}<span>${t==='My stable'?'Stable':t==='Trail ride'?'Trail':t}</span></a>`).join('');$('#crumb').textContent=({home:'Home',stable:'My stable',community:'Community',trail:'Trail ride',offline:'Install & offline',profile:'My stable',world:'3D world',account:'Your account'})[route];document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
function connection(){const offline=!navigator.onLine||offlinePreview;$('#connection').innerHTML=`<i></i>${offline?'Offline':'Online'}`;$('#offline-banner').hidden=!offline;$('#offline-banner').textContent=offlinePreview?'Offline preview · Try care, horse profiles and a trail ride. Changes stay on this device.':'You’re offline · Your stable, care and trail ride are available. Progress saves on this device.';}
const meter=(name,val,warm=false)=>`<div class="meter-row"><label>${name}<span>${val}%</span></label><div class="meter ${warm?'warm':''}" role="meter" aria-label="${name}" aria-valuenow="${val}" aria-valuemin="0" aria-valuemax="100"><i style="width:${val}%"></i></div></div>`;
function postHTML(p){const comments=[...(Array.isArray(p.comments)?p.comments:[]),...(Array.isArray(state.comments[p.id])?state.comments[p.id]:[])];return `<article class="post"><div class="post-body"><div class="post-head"><span class="avatar ${['sage','clay','lilac'].includes(p.avatar)?p.avatar:''}">${esc(p.initials)}</span><div class="post-author">${esc(p.name)}<small>${esc(p.time)}${p.local?(Cloud?.active?' · Private account note':' · On this device'):''}</small></div><span class="post-tag">${esc(p.tag||'YOUR UPDATE')}</span></div>${p.title?`<h3>${esc(p.title)}</h3>`:''}<p>${esc(p.text)}</p>${['willow.webp','atlas.webp','sunny.webp'].includes(p.image)?`<img class="post-photo" src="assets/${esc(p.image)}" alt="${p.image==='sunny.webp'?'Golden palomino in the afternoon sun':p.image==='atlas.webp'?'Dapple gray horse in a green paddock':'Chestnut horse in a peaceful green paddock'}" loading="lazy">`:''}</div><div class="post-actions"><button data-action="like" data-id="${esc(p.id)}" aria-label="${state.liked.includes(p.id)?'Unlike':'Like'} ${esc(p.name)}’s post" aria-pressed="${state.liked.includes(p.id)}" class="${state.liked.includes(p.id)?'liked':''}">${icon('heart')} ${(Number.isFinite(p.likes)?Math.max(0,Math.floor(p.likes)):0)+Number(state.liked.includes(p.id))}</button><button data-action="comments" data-id="${esc(p.id)}" aria-label="Comments on ${esc(p.name)}’s post">${icon('comment')} ${comments.length} <span>Comments</span></button><button data-action="bookmark" data-id="${esc(p.id)}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} post" aria-pressed="${state.saved.includes(p.id)}">${icon(state.saved.includes(p.id)?'check':'bookmark')}</button></div></article>`;}
function posts(){let list=[...state.posts,...samplePosts].filter(p=>p&&typeof p==='object');if(feedTab==='mine')list=list.filter(p=>p.local);if(feedTab==='saved')list=list.filter(p=>state.saved.includes(p.id));if(query)list=list.filter(p=>(p.text+' '+p.title+' '+p.name).toLowerCase().includes(query.toLowerCase()));return list.length?list.map(postHTML).join(''):`<div class="empty-state"><h3>${query?'No matching moments.':feedTab==='mine'?'Your story belongs here.':'Keep your favorite moments.'}</h3><p>${query?'Try another name or word.':feedTab==='mine'?'Share a little update from your stable.':'Tap the bookmark on any community post to save it.'}</p>${feedTab==='mine'?'<button class="primary" data-action="compose">Share your first update</button>':''}</div>`;}
function feed(){return `<div class="feed-tabs" role="tablist" aria-label="Community feed"><button class="tab ${feedTab==='all'?'active':''}" role="tab" aria-selected="${feedTab==='all'}" data-tab="all">All updates</button><button class="tab ${feedTab==='mine'?'active':''}" role="tab" aria-selected="${feedTab==='mine'}" data-tab="mine">My updates</button><button class="tab ${feedTab==='saved'?'active':''}" role="tab" aria-selected="${feedTab==='saved'}" data-tab="saved">Saved</button></div><div class="compose"><span class="avatar">${esc(playerInitials())}</span><button data-action="compose">What’s happening in your stable?</button>${icon('image')}</div><div id="posts">${posts()}</div>`;}
function stableMini(){return `<section class="card"><div class="card-heading"><h3>Your happy herd</h3><span class="pill">${state.horses.length} HORSE${state.horses.length>1?'S':''}</span></div>${state.horses.slice(0,5).map(h=>`<div class="horse-mini"><img src="${pic(h)}" alt="${esc(h.name)}"><div class="horse-meta"><b>${esc(h.name)}</b><small><i class="status-dot ${completed(h)<3?'warm':''}"></i>${completed(h)===3?'All cared for today':completed(h)+' of 3 care tasks done'}</small></div><button data-horse="${h.id}" aria-label="Visit ${esc(h.name)}">↗</button></div>`).join('')}<div class="care-foot"><button class="primary full" data-route="stable">A little care goes a long way ${icon('arrow')}</button><p>Earn up to 30 points per horse, each day.</p></div></section>`;}
function eventCard(){return `<section class="card event-card"><div class="eyebrow">A LITTLE ADVENTURE</div><div class="event-art">⌁ ⌁ ⌁</div><h3>The autumn<br>trail ride</h3><p>Three quiet moments. One good friend.<br>A trail that’s yours to discover.</p><div class="event-time">${icon('clock')} About 2 minutes · +30 points</div><button data-route="trail">Take the scenic route <span>↗</span></button></section>`;}
// Home is the stall, full screen (body.home-3d): the page chrome floats over it and the rest of the site opens
// from the dock. The old dashboard (greeting, summary, feed) is no longer drawn here; Community still has the feed.
function home(){return homeHero();}
function stable(){if(ranchMode())return TR.stablePage()+worldEntry();return `<section class="page-title"><div class="eyebrow">A HOME FOR EVERY HEART</div><div class="section-heading"><h1>Your stable</h1><span class="balance">✧ ${state.points} points</span></div><p>${state.horses.length} demo companions. A little care. A bond that keeps growing.</p></section>${worldEntry()}${window.HorselandiaStable.scene(state.horses,playerName())}<p class="stable-capacity-note">Starter wing · Three sample horses for this playtest. Additional horses and barn expansions are not available yet; the final stable capacity hasn’t been decided.</p><div class="stable-overview-heading"><h2>Your companions</h2><span>Choose a stall above or a horse below.</span></div><div class="notice">${icon('leaf')}<div>Horse time moves a little faster here: <b>1 real day = 1 horse month.</b> Care tasks refresh each day. ${progressNote()}</div></div><div class="horse-grid">${state.horses.map(h=>`<article class="horse-card"><img src="assets/${h.image}" alt="${esc(h.name)}, ${h.color.toLowerCase()} horse"><div class="horse-card-content"><span class="eyebrow muted">${h.trait}</span><h2>${esc(h.name)}</h2><p class="breed">${h.breed} · ${h.color}</p><div class="horse-facts"><div><b>${age(h)}</b>Horse age</div><div><b>${completed(h)} / 3</b>Care today</div><div><b>${h.bond}%</b>Bond</div></div>${meter('Happiness',h.happiness)}${meter('Energy',h.energy,true)}<button class="primary" data-horse="${h.id}">Visit ${esc(h.name)} ${icon('arrow')}</button></div></article>`).join('')}</div><p class="local-label">${progressNote()}</p>`;}
// 2026-11-15 playtest: kids could open the 'Owner setup · Supabase & Google' form (project URL / key fields). Only on a local
// dev host, or when no project is connected yet.
const ownerSetupVisible=()=>/^(localhost|127\.0\.0\.1|\[::1\])$/.test(location.hostname)||!window.MEADOWGATE_SUPABASE?.url;
function profile(){const h=horse(selected);return `<button class="back-button" data-route="stable">← Back to your stable</button><div class="profile-layout"><img class="profile-image" src="${pic(h,{w:720,h:460})}" alt="${esc(h.name)}, ${h.color.toLowerCase()} horse"><section class="profile-detail"><div class="eyebrow muted">${h.trait}</div><div class="profile-heading"><h1>${esc(h.name)}</h1><button class="secondary" data-action="rename" data-id="${h.id}">${icon('edit')} Rename</button></div><p>${h.breed} · ${h.color}</p><a class="primary world-profile-link" href="#world/${esc(h.id)}">Ride ${esc(h.name)} in the 3D world ${icon('arrow')}</a><p style="margin-top:16px">${h.bio}</p><div class="horse-facts" style="margin-top:24px"><div><b>${age(h)}</b>Horse age</div><div><b>${h.bond}%</b>Your bond</div>${ranchMode()?`<div><b>Lv ${TR.R.level(h.xp)}</b>Level</div>`:`<div><b>${state.points}</b>Your points</div>`}</div>${meter('Happiness',h.happiness)}${meter('Energy',h.energy,true)}${ranchMode()?TR.profileExtras(h):`<div class="care-buttons">${[['feed','feed','Feed','A favorite treat'],['groom','brush','Groom','A little shine'],['bond','heart','Bond','A quiet moment']].map(([action,i,t,d])=>`<button class="care-button ${cared(h.id,action)?'done':''}" data-action="care" data-care="${action}" data-id="${h.id}" ${cared(h.id,action)?'disabled':''}>${icon(cared(h.id,action)?'check':i)}<b>${t}</b><small>${cared(h.id,action)?'Done today':'+10 points · '+d}</small></button>`).join('')}</div><p class="small">${completed(h)===3?'All cared for. Come back tomorrow for three new moments together.':'Each care action earns points once per day. Account rewards are verified when connected; the day resets at midnight UTC.'}</p>`}<div class="badge-row">${h.bond>=75?'<span class="badge">♡ Trusted companion</span>':''}${completed(h)===3?'<span class="badge">✳ Daily care complete</span>':''}</div><div class="journal"><h3>Your little moments</h3>${state.journal.filter(j=>j.horse===h.id).slice(0,5).map(j=>`<div class="journal-entry">${icon('leaf')}<div>${esc(j.text)}<br><span>${esc(j.day)} · +${j.points} points</span></div></div>`).join('')||'<p class="small">Your first care moment is waiting. Try feeding, grooming, or bonding.</p>'}</div></section></div>`;}
const trailQuestions=[{title:'A fork in the trail.',text:'The wide path is quiet. A narrow shortcut cuts across a muddy slope. Where will you lead your companion?',choices:['Stay on the wide, steady path','Try the muddy shortcut'],good:0,feedback:['A little patience goes a long way. Your companion settles into an easy rhythm.','The footing feels uncertain. You turn back to the wide path and keep the ride comfortable.']},{title:'Something in the leaves.',text:'A rustle in the hedgerow makes your companion pause, ears high. What do you do?',choices:['Rush past the noise','Pause, reassure, and let them look'],good:1,feedback:['You notice the tension, slow down, and give your companion a reassuring moment.','One calm moment later, those ears soften. Trust is built in little moments like these.']},{title:'The meadow opens up.',text:'You reach a sunny clearing. There’s time for one last moment before heading home.',choices:['Take a breather and enjoy the view','Race straight back to the stable'],good:0,feedback:['You loosen the reins and take in the view. Some rides are about being here, together.','Home is tempting, but you choose a gentle walk for the last stretch. A happy ending for both of you.']}];
function trail(){const done=state.rides[`${day()}:${selected}`];const h=horse(selected);let content;if(!trailSession){content=`<div class="trail-hero"><div class="landscape" aria-hidden="true">⌁ ⌂</div><div class="eyebrow">THE MEADOW LOOP</div><h2>Take the scenic route.</h2><p>A short, story-led ride. Make three choices, build a little trust, and bring home a memory. No timer. No rush.</p><div class="form-row"><label for="trail-horse">Your trail companion</label><select id="trail-horse">${state.horses.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.name)} · ${age(x)}</option>`).join('')}</select></div><button class="primary" data-action="start-trail">Saddle up ${icon('arrow')}</button><p class="small" style="margin-top:13px">${done?'You’ve earned today’s reward with this horse. You can ride again for the story.':'Complete the ride for +30 points and +8 bond. One reward per horse, per day.'}</p></div>`;}else if(trailSession.finished){content=`<div class="card" style="text-align:center;padding:40px 25px"><div class="eyebrow">BACK WHERE YOU BELONG</div><div class="reward">${trailSession.rewarded?'+30':'♡'}</div><h2>A good ride. A closer bond.</h2><p style="margin:17px auto;max-width:440px">You and ${esc(h.name)} found your way through the meadow. ${trailSession.rewarded?(Cloud?.active?(Cloud.status==='synced'?'Your +30 points and +8 bond are saved to your account.':'Your +30 points and +8 bond are pending server verification.'):'You earned 30 points and strengthened your bond by 8.'):'Today’s reward is already in your stable. This one was for the memories.'}</p><div class="badge-row" style="justify-content:center"><span class="badge">✧ ${state.points} total points</span><span class="badge">♡ ${h.bond}% bond</span></div><button class="primary" style="margin-top:25px" data-horse="${h.id}">Back to ${esc(h.name)}</button><button class="secondary" style="margin-top:12px" data-action="share-ride">Share the memory</button><button class="text-button" style="display:block;margin:20px auto 0" data-action="ride-again">Ride again</button></div>`;}else{const q=trailQuestions[trailSession.step];content=`<div class="route-steps">${['The fork','The hedgerow','The clearing'].map((t,i)=>`<span class="route-step ${i<=trailSession.step?'current':''}"><i>${i<trailSession.step?'✓':i+1}</i>${t}</span>`).join('')}</div><section class="card" style="padding:30px"><div class="eyebrow muted">YOU & ${esc(h.name.toUpperCase())} · MOMENT ${trailSession.step+1} OF 3</div><h2 style="margin:18px 0 12px">${q.title}</h2><p style="font-size:13px;margin-bottom:22px">${q.text}</p>${q.choices.map((c,i)=>`<button class="choice ${trailSession.choice===i?'chosen':''}" data-choice="${i}" ${trailSession.choice!==null?'disabled':''}>${esc(c)}</button>`).join('')}${trailSession.choice!==null?`<div class="feedback">${q.feedback[trailSession.choice]}</div><button class="primary full" data-action="next-trail">${trailSession.step===2?'Return to the stable':'Continue the trail'} ${icon('arrow')}</button>`:''}</section>`;}return `<div class="trail-wrap"><a class="secondary world-profile-link" href="#world">Prefer to ride in 3D? Enter the meadow ↗</a><section class="page-title"><div class="eyebrow">OFFLINE FRIENDLY · ABOUT 2 MINUTES</div><h1>The autumn trail ride</h1><p>A little adventure, right from your pocket.</p></section>${content}<p class="local-label">This is a gentle virtual activity, not riding instruction. ${progressNote()}</p></div>`;}
function community(){return `<section class="page-title"><div class="eyebrow">FAMILIAR FACES. FRESH STARTS.</div><h1>Your kind of people.</h1><p>A welcoming corner for horse stories, small wins, and old friends.</p></section><div class="notice">${icon('people')}<div>You’re exploring a sample community. ${Cloud?.active?'Your personal updates, notes and memberships sync only to your account.':'Updates, notes and memberships save on this device.'}</div></div><div class="community-layout"><section><label class="sr-only" for="search">Search community updates</label><input class="search" id="search" type="search" placeholder="Find a story, a friend, a little inspiration…" value="${esc(query)}">${feed()}</section><aside><section class="card"><div class="card-heading"><h3>Find your circle</h3><span class="pill">SAMPLE CLUBS</span></div>${[['trail','⌁','The Trail Club','For the scenic-route people'],['return','⌂','Back in the Saddle','Old friends, new beginnings'],['art','✳','Paddock Creatives','Horse art, photography & stories']].map(([id,s,t,d])=>`<div class="club"><span class="club-icon">${s}</span><div><b>${t}</b><p>${d}</p></div><button data-action="club" data-id="${id}" aria-pressed="${state.clubs.includes(id)}">${state.clubs.includes(id)?'Joined ✓':'Join'}</button></div>`).join('')}</section><section class="card event-card"><div class="eyebrow">A PLACE TO RECONNECT</div><h3>The welcome circle</h3><p>A sample community gathering for sharing your first horse story. RSVP to put it on your local list.</p><div class="event-time">Every Saturday · 2:00 pm Eastern<br>Prototype event · No real meeting</div><button data-action="rsvp" aria-pressed="${state.joined}">${state.joined?'You’re on the local list ✓':'Count me in ↗'}</button></section>${eventCard()}</aside></div>`;}
const guides={ios:[['Open in Safari','Open this private link in Safari and sign in to ChatGPT if asked.'],['Add to Home Screen','Tap Share, choose Add to Home Screen, then enable Open as Web App if shown.'],['Make it yours','Tap Add. Open Trottville from its new home-screen icon.']],android:[['Open in Chrome','Open this private link in Chrome, rather than inside another app.'],['Install Trottville','Use the Install button below if offered, or Chrome’s ⋮ menu → Add to home screen / Install app.'],['Visit once, then take it offline','Wait for “Offline ready” below, then open your stable. Try airplane mode and reopen the app.']],desktop:[['Use Chrome or Edge','Open the private link and sign in to ChatGPT if asked.'],['Install from the address bar','Select the browser’s install icon, or use its menu → Install Trottville.'],['Open it like an app','Launch from your applications. Your stable stays available after the offline cache is ready.']]};
function offline(){return `<section class="page-title"><div class="eyebrow">YOUR STABLE, IN YOUR POCKET</div><h1>A web app. A familiar feeling.</h1><p>Install from your browser. Visit your horses even when the signal disappears.</p></section><div class="offline-grid"><section class="card"><div class="card-heading"><h3>Make yourself at home</h3>${icon('download')}</div><div class="platform-tabs" role="tablist" aria-label="Install platform">${[['android','Android'],['ios','iPhone / iPad'],['desktop','Desktop']].map(([v,t])=>`<button class="${platform===v?'active':''}" role="tab" aria-selected="${platform===v}" data-platform="${v}">${t}</button>`).join('')}</div><ol class="guide-steps">${guides[platform].map(([a,b])=>`<li><strong>${a}</strong>${b}</li>`).join('')}</ol><button class="primary full" data-action="native-install">${icon('download')} ${matchMedia('(display-mode: standalone)').matches?'Already running as an app':deferredInstall?'Install Trottville':'Check installation options'}</button><p class="local-label">Installation depends on your browser. Open the deployed link in Safari, Chrome, or Edge; embedded previews may not offer installation. First access requires an internet connection and your private sign-in.</p></section><section><div class="card"><div class="card-heading"><h3>Room for a little offline life</h3>${icon('wifi')}</div><div class="status-box" role="status"><b id="cache-status">${cacheStatus}</b><small>${cacheReady?'Core screens and all horse images are saved on this device.':'The first visit needs a connection. Keep this page open while the core saves.'}</small></div><ul class="offline-list"><li>Horse profiles & names <span>Available offline</span></li><li>Daily care, points & journal <span>Available offline</span></li><li>The autumn trail ride <span>Available offline</span></li><li>Sample feed & local posts <span>Available offline</span></li><li>Live community feed <span>Sample only</span></li></ul><button class="secondary full" data-action="verify-cache">Verify offline files</button><label class="preview-toggle"><input id="offline-preview" type="checkbox" ${offlinePreview?'checked':''}> Preview the offline experience</label><p class="small">Preview shows offline behavior without disconnecting. To test a real offline launch: wait for Offline ready, switch to airplane mode, then close and reopen the installed app.</p></div><div class="card"><h3 style="font-family:var(--serif);font-size:21px;margin-bottom:10px">A prototype with room to grow.</h3><p class="small">${progressNote()} Google sign-in opens a separate stable for your account. The community feed remains a sample; personal notes sync privately.</p><button class="text-button" style="margin-top:17px" data-action="export">Export my prototype progress ↗</button></div></section></div>`;}
function worldEntry(){return `<section class="world-entry"><div><div class="eyebrow">NEW · YOUR FIRST PLAYABLE MEADOW</div><h2>Beyond the stable doors.</h2><p>Walk through a colorful 3D landscape, ride your companions, and find five golden meadow markers.</p></div><a class="primary" href="#world">Enter the 3D world ${icon('arrow')}</a></section>`;}
function world(){return window.HorselandiaWorld.render(worldHorses());}
// Home greeting: the selected horse live in 3D (home-horse.js), Pet / Feed / Brush, and "what next" suggestions.
// The 3D view is created once and moved into each fresh render, so likes and other re-renders don't rebuild it.
let homeHorse=null,homeHorseLoading=null,suggestMod=null,worldIntent=null;
// Faster start: on the home route, fetch three.js + the stall/horse modules right away (modulepreload removes the
// import waterfall) and start the import before the ranch loads and the page draws.
const HOME_3D=['vendor/three-0.180.0/three.core.js','vendor/three-0.180.0/three.module.js','horse-sculpt.js','stall-decor.mjs','stall-scene.js','character-looks.mjs','stall-ui.js','home-horse.js'];
let homeHorseMod=null;
const loadHomeHorse=()=>homeHorseMod||=import('./home-horse.js?v=158').catch(err=>{homeHorseMod=null;throw err;});
if(/^#?(home|world.*)?$/.test(location.hash)){for(const href of [...HOME_3D,...(/^#?home$/.test(location.hash)?[]:['world.js'])]){if(document.querySelector(`link[href="${href}"]`))continue;const l=document.createElement('link');l.rel='modulepreload';l.href=href;document.head.append(l);}loadHomeHorse().catch(()=>{});}
const HOME_CARE={pet:'bond',feed:'feed',groom:'groom'};
// 2026-11-15 playtest: an unwell horse showed nothing at home. A red pill opens the vet (data-ranch="vet" is handled by ranch-ui).
function homeVetPill(){if(!TR||!ranchMode())return '';const rh=TR.get()?.herd.find(x=>x.id===selected);if(!rh||TR.R.condition(rh).id!=='unwell')return '';return `<button type="button" class="h3-vet" data-ranch="vet" data-v="${esc(rh.id)}">🩺 ${esc(rh.name)} is unwell · see the vet</button>`;}
function homeHero(){const h=horse(selected);return `<section class="hero hero-live is-live"><div class="hero-live-slot" id="home-horse-slot"></div>${homeVetPill()}<div class="h3-today-wrap"><button type="button" class="h3-today" aria-expanded="false" aria-controls="h3-today-panel"><img class="px-ic" src="assets/icons/quests.webp" alt="" aria-hidden="true" draggable="false"> Today <b></b></button><div class="h3-today-panel" id="h3-today-panel" hidden><section class="home-next" id="home-next" aria-label="Things to do today"></section><div class="h3-audio h3-tools"><button type="button" class="h3-feedback" data-feedback="home" aria-label="Send feedback">💬 Feedback</button><button type="button" class="h3-feedback" data-audio="sounds">🔊 Sounds</button><button type="button" class="h3-feedback" data-audio="music">🎵 Music</button><button type="button" class="h3-feedback" data-audio="gfx">✨ Effects</button></div></div></div>
<nav class="h3-dock" aria-label="Go to"><a href="#world" class="h3-main" aria-label="Go out" title="Go out"><img class="px-ic h3-ic" src="assets/icons/saddle.webp" alt="" aria-hidden="true" draggable="false"></a><button type="button" data-home-go="panel:games" aria-label="Games" title="Games"><img class="px-ic h3-ic" src="assets/icons/games.webp" alt="" aria-hidden="true" draggable="false"></button><button type="button" data-home-go="panel:stable" aria-label="Stable" title="Stable"><img class="px-ic h3-ic" src="assets/icons/horse-head.webp" alt="" aria-hidden="true" draggable="false"></button><button type="button" data-friends="open" aria-label="Friends" title="Friends"><img class="px-ic h3-ic" src="assets/icons/friends.webp" alt="" aria-hidden="true" draggable="false"></button><button type="button" data-home-go="store" aria-label="Store" title="Store"><img class="px-ic h3-ic" src="assets/icons/store.webp" alt="" aria-hidden="true" draggable="false"></button></nav>
<div class="hero-horses" role="group" aria-label="Choose a horse">${(()=>{const l=state.horses.slice(0,5);if(!l.includes(h))l[l.length-1]=h;return l;})().map(x=>`<button type="button" data-home-horse="${x.id}" aria-pressed="${x.id===h.id}">${esc(x.name)}</button>`).join('')}${state.horses.length>5?`<button type="button" data-route="stable">All ${state.horses.length}</button>`:''}${ranchMode()?xpMeter():''}</div>${ranchMode()?'':`<div class="hero-care" role="group" aria-label="Care for ${esc(h.name)}">${[['pet','💗','Pet'],['feed','🥕','Feed'],['groom','🪮','Brush']].map(([k,e,l])=>`<button type="button" data-home-care="${k}" class="${cared(h.id,HOME_CARE[k])?'done':''}"><span aria-hidden="true">${e}</span>${l}</button>`).join('')}</div>`}</section>`;}
function homeAttach(){const slot=$('#home-horse-slot');if(!slot)return;
  if(homeHorse){slot.append(homeHorse.el);if(homeHorse.horse.id!==selected)homeHorse.setHorse(horse(selected));}
  else if(!homeHorseLoading)homeHorseLoading=loadHomeHorse().then(m=>{homeHorse=window.__homeHorse=m.createHomeHorse({horse:horse(selected),onCare:homeCare,basket:homeBasket,drawCarrot:homeDraw,rest:()=>ranchMode()&&TR.horse(selected)?TR.R.restNow(TR.horse(selected)):100});homeHorseLoading=null;if(homeHorse)homeAttach();}).catch(()=>{homeHorseLoading=null;});
  homeSuggest();}
let lastDraw=null;
function homeBasket(h){if(!ranchMode())return {left:5,free:true,golden:0};const x=TR.horse(h.id);return x?{...TR.R.basketFor(TR.get(),x),golden:TR.get().food.golden||0}:{left:0};}
function homeDraw(h){if(!ranchMode())return Math.random()<1/50?'golden':'carrot';const x=TR.horse(h.id);lastDraw=x?TR.R.drawCarrot(TR.get(),x):null;return lastDraw?.item||null;}
// The 3D world's stall uses the same care rules as the home page (one world, 2026-11-12).
window.TrottCare={onCare:(k,h,i)=>homeCare(k,h,i),basket:h=>homeBasket(h),drawCarrot:h=>homeDraw(h),rest:h=>ranchMode()&&TR?.horse?.(h.id)?TR.R.restNow(TR.horse(h.id)):100};
// XP meter under the horse's name: level, progress bar and how much is left to the next level.
function xpMeter(){const h=TR?.horse?.(selected);if(!h)return '';const R=TR.R,l=R.level(h.xp),a=R.levelFloor(l),b=R.levelFloor(l+1),xp=h.xp||0,p=Math.max(0,Math.min(100,Math.round((xp-a)/(b-a)*100)));
  return `<div class="h3-xp" id="h3-xp" role="meter" aria-valuemin="0" aria-valuemax="${b-a}" aria-valuenow="${xp-a}" aria-label="${esc(h.name)} level ${l}: ${b-xp} XP to level ${l+1}"><b>Lv ${l}</b><i><s style="width:${p}%"></s></i><small>${(b-xp).toLocaleString()} XP to Lv ${l+1}</small></div>`;}
function paintXP(){const old=$('#h3-xp');if(!old)return;const t=document.createElement('div');t.innerHTML=xpMeter();const n=t.firstElementChild;if(!n)return;
  const up=+(old.querySelector('b')?.textContent.slice(3))<+(n.querySelector('b').textContent.slice(3));old.replaceWith(n);if(up){n.classList.add('up');toast(`Level up! ${TR.horse(selected)?.name} reached ${n.querySelector('b').textContent}.`);}}
function homeCare(kind,h,info={}){window.TrottLog?.log('care',{a:kind});if(ranchMode()){let out;
    if(kind==='pet'||kind==='groom'||kind==='tidy'){if(info.noXp)return {};const r=ranchCare(h.id,kind,{coins:true});out={xp:r?.xp};}
    else{const d=lastDraw||{item:info.item||'carrot'};lastDraw=null;const res=TR.R.feed(TR.get(),h.id,{item:d.item,fromGolden:!!d.fromGolden});
      if(!res.ok){if(res.vet)setTimeout(()=>TR.openVet(h.id),900);return {ok:false,reason:res.reason};}
      // v127: a sulking horse still eats (hunger is fed) but the meal earns no XP or Trotties.
      if(info.noXp){const old=TR.horse(h.id)?.xp||0;TR.set({...res.ranch,herd:res.ranch.herd.map(x=>x.id===h.id?TR.R.fromPlain({...TR.R.toPlain(x),xp:old}):x)},{quiet:true});out={ok:true,xp:0};}
      else{TR.set(res.ranch,{quiet:true});TR.queueCare(res.horse,"feed");out={ok:true,xp:res.xp};}}
    homeSuggest();paintBell();paintXP();return out;}
  if(info.noXp)return {};if(kind==='golden')kind='feed';const action=HOME_CARE[kind];if(!action)return {};
  if(cared(h.id,action))toast(({pet:`${h.name} leans into the pat.`,feed:`${h.name} happily munches. Today’s treat points are already in.`,groom:`${h.name} shines. Today’s brushing points are already in.`})[kind]);
  else care(h.id,action,{silent:true});
  $(`[data-home-care="${kind}"]`)?.classList.toggle('done',cared(h.id,action));const pts=$('#home-points');if(pts)pts.firstChild.textContent=state.points+' ';homeSuggest();}
function ranchFacts(){if(!ranchMode())return {};const r=TR.get(),sp=TR.R.marketStock(TR.R.dayNo(),r.bought).shelf.find(l=>l.tier==='special');return {ranchAlerts:TR.R.alerts(r),special:sp?{...sp,breed:TR.R.breedOf(sp.breedId).name}:null};}
// The store menu (home dock): every shop in one small sheet.
// Note #24: 'Go out' is always open (you start on foot in the barn); tack is bought from Otis in the barn's Tack room.
function rideLocked(){return !!(ranchMode()&&TR?.horse?.(selected)&&TR.missingTack(selected).length);}
window.addEventListener('ranch:tack',()=>{if(route==='home')render();});
function openStoreMenu(){$('.h3-sheet')?.remove();const d=document.createElement('div');d.className='h3-sheet';d.setAttribute('role','dialog');d.setAttribute('aria-modal','true');d.setAttribute('aria-label','Store');
  d.innerHTML=`<div class="h3-sheet-card"><header><h2>Store</h2><button type="button" class="h3-x" aria-label="Close">✕</button></header>${[['food','🥕','Food and treats','Carrots, apples and hay for your herd'],['horses','🐴','Horse market','New horses arrive every day'],['decor','🪴','Stall decor','Pictures, plants, rugs and more'],['outfits','👕','Rider outfits','Try them on in the 3D world']].map(([k,i,t,x])=>`<button type="button" class="h3-shop${k==='tack'&&TR.missingTack(selected).length?' h3-shop-hot':''}" data-shop="${k}"><span aria-hidden="true">${i}</span><span><b>${t}</b><small>${x}</small></span></button>`).join('')}</div>`;
  // 2026-11-15 playtest: Android Back left the Store floating over the next page: close it on any hash change.
  let hist=false;const close=()=>{d.remove();document.removeEventListener('keydown',esc2);removeEventListener('hashchange',close);removeEventListener('popstate',onPop);},esc2=e=>{if(e.key==='Escape')userClose();};addEventListener('hashchange',close);
  // Round 2: Android Back closes the Store and stays on the page (one history step while it's open).
  const onPop=()=>{hist=false;close();},userClose=()=>{const h=hist;hist=false;close();if(h)history.back();};addEventListener('popstate',onPop);try{history.pushState({...(history.state||{}),storeSheet:1},'');hist=true;}catch{}
  d.addEventListener('click',e=>{if(e.target===d||e.target.closest('.h3-x'))return userClose();const k=e.target.closest('[data-shop]')?.dataset.shop;if(!k)return;close();
    if(k==='tack')TR?.openTack?.(selected);else if(k==='food')TR?.openStore?.();else if(k==='horses')TR?.openMarket?.();else if(k==='decor')homeHorse?.store();else{worldIntent='me';go('world');}});
  document.addEventListener('keydown',esc2);document.body.append(d);d.querySelector('.h3-x').focus();}
document.addEventListener('click',e=>{const t=e.target.closest('.h3-today');if(!t){const p=$('#h3-today-panel');if(p&&!p.hidden&&!e.target.closest('.h3-today-panel')){p.hidden=true;$('.h3-today')?.setAttribute('aria-expanded','false');}return;}const p=$('#h3-today-panel'),on=p.hidden;p.hidden=!on;t.setAttribute('aria-expanded',on);});
function homeSuggest(){const box=$('#home-next');if(!box)return;
  if(!suggestMod){import('./home-suggestions.mjs?v=158').then(m=>{suggestMod=m;homeSuggest();}).catch(()=>{});return;}
  const read=k=>{try{return JSON.parse(localStorage.getItem(k));}catch{return null;}},key='horselandia-adventure-v1:'+(Cloud?.active?Cloud.user.id:'guest');
  const w=read('trottville-wallet-v1'),wallet={coins:200,stars:0,owned:['stablehand','meadow','trail','hoodie'],...(w||{})},adv=read(key)||{},trust={willow:68,atlas:81,sunny:54,...(read(key+':trust')||{})};
  const h=horse(selected),left=ranchMode()?['pet','feed','groom'].filter(k=>!TR.get().careDay[`${TR.R.dayNo()}:${h.id}:coin:${k}`]).map(k=>HOME_CARE[k]):['bond','feed','groom'].filter(a=>!cared(h.id,a));
  const list=suggestMod.suggestions({wallet,visited:(adv.visited||[]).length,trust,horses:state.horses.map(x=>({id:x.id,name:x.name})),careLeft:[{name:h.name,actions:left}],dayIndex:Math.floor(Date.now()/864e5),...ranchFacts()});
  const pill=$('.h3-today b');if(pill){pill.textContent=list.length?String(list.length):'✓';$('.h3-today').classList.toggle('urgent',list.some(x=>x.id==='vet'||x.id==='food'));}
  box.innerHTML=list.length?`<h2>Things to do</h2><div class="home-next-list">${list.map(x=>`<article class="home-next-card"><span class="home-next-icon" aria-hidden="true">${x.icon}</span><div><b>${esc(x.title)}</b><p>${esc(x.text)}</p></div><button type="button" data-home-go="${x.go}">${esc(x.label)}</button></article>`).join('')}</div>`:'';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-home-care],[data-home-horse],[data-home-go]');if(!b)return;
  if(b.dataset.homeCare){homeHorse?homeHorse.play(b.dataset.homeCare):homeCare(b.dataset.homeCare,horse(selected));return;}
  if(b.dataset.homeHorse){if(b.dataset.homeHorse===selected&&document.body.classList.contains('home-3d')){const g=b.closest('.hero-horses');g.classList.toggle('open');b.setAttribute('aria-expanded',g.classList.contains('open'));return;}selected=b.dataset.homeHorse;render();return;}
  if(b.dataset.homeGo==='store'){openStoreMenu();return;}
  const g=b.dataset.homeGo;if(g.startsWith('care:')){const k=Object.keys(HOME_CARE).find(k=>HOME_CARE[k]===g.slice(5));$('.hero-live')?.scrollIntoView({behavior:'smooth',block:'center'});homeHorse?homeHorse.play(k):homeCare(k,horse(selected));return;}
  if(g.startsWith('panel:')){if(window.TrottPanels)window.TrottPanels.open(g.slice(6));else go(g.slice(6)==='stable'?'stable':'world');return;}
  if(g==='tackroom')document.querySelectorAll('.rn-sheet').forEach(s=>s.remove());
  if(g.startsWith('ranch:')){TR?.[{vet:'openVet',market:'openMarket',store:'openStore'}[g.slice(6)]]?.();return;}worldIntent=g;go('world');});
// Ranch (ranch-ui.js): a herd of 1–100 horses, food, the vet, the horse market and Trotties. Device-only
// for now, so it stays off while a cloud account is signed in (that stable's three horses are server-checked).
let TR=null;
const ranchMode=()=>!!TR&&(!Cloud?.active||!!window.TrottAccountRanch?.on);
const ranchReady=import('./ranch-ui.js?v=158').then(m=>{TR=m;}).catch(()=>{});
function applyRanch(){if(!ranchMode())return false;const r=TR.get();if(!r?.herd.length)return false;state.horses=r.herd;if(!r.herd.some(h=>h.id===selected))selected=(r.herd.find(h=>h.free)||r.herd[0]).id;return true;}
const needsStarter=()=>ranchMode()&&!TR.get()?.herd.length;
// Every horse picture is the same sculpted horse as the world (ranch-ui portrait); photos only if that can't load.
const pic=(h,size)=>TR?TR.portrait(h,size):h.image?'assets/'+h.image:'assets/horse-icon.svg';
// The world draws a few companions, not the whole herd: the chosen horse plus two more.
// v124: only horses in a stall come out in the 3D world (pasture horses wait behind the barn); the one you picked first.
const worldHorses=()=>ranchMode()?[horse(selected),...state.horses.filter(h=>h.id!==selected&&!h.pasture)].slice(0,3):state.horses;
function paintBell(){const n=TR?TR.bellCount():0,d=$('#bell .bell-dot');if(d)d.hidden=!n;TR?.Coins.paintCounters();}
function ranchCare(id,kind,{coins=false}={}){const r=TR.R.care(TR.get(),id,kind);if(!r)return null;TR.set(r.ranch,{quiet:true});if(coins&&r.first)TR.queueCare(r.horse,kind);paintBell();return r;}
// A first launch with no hash lands on 'world', which draws the starter page until a horse is chosen: it must redraw too.
window.addEventListener('ranch:change',()=>{if(route!=='world'||needsStarter())render();paintBell();});
window.addEventListener('trottcoins:change',paintBell);
window.addEventListener('ranch:carehome',e=>{selected=e.detail;go('home');});
document.addEventListener('click',e=>{if(e.target.closest('#bell')){TR?.openBell();}else if(e.target.closest('#tc-counter')){if(TR?.Coins.pending())TR.Coins.showCollect({title:'Trotties waiting for you'});else toast('Trotties: earn them in games, races and caring for your horses.');}});
// Nothing draws until the ranch module has loaded, so the first frame is already your own stable (no sample
// horse or empty page flashing first). body.booted also reveals the footer.
let booted=false;
function render(){if(!booted)return;applyRanch();window.HorselandiaWorld?.dispose();if(homeHorse&&route!=='home'){homeHorse.dispose();homeHorse=null;}document.body.classList.toggle('game-active',route==='world'&&!needsStarter());document.body.classList.toggle('rn-adopt',needsStarter()&&!cloudLoading&&['home','stable','profile','world','trail'].includes(route));document.body.classList.toggle('acct-page',route==='account');document.body.classList.toggle('home-3d',route==='home'&&!needsStarter()&&!cloudLoading);nav();connection();$('#main').innerHTML=(!storageOK?'<p class="storage-warning" role="alert">Browser storage is unavailable. Progress won’t survive closing this page.</p>':'')+(cloudLoading&&route!=='account'&&route!=='world'?'<section class="page-title"><h1>Opening your stable…</h1><p>'+esc(Cloud.message)+'</p></section><button class="secondary" data-route="account">Your account</button>':(needsStarter()&&['home','stable','profile','world','trail'].includes(route)?TR.starterPage():({home,stable,profile,world,trail,community,offline,account}[route]||home)()))+cloudStatusHTML();window.HorselandiaBackgrounds?.attach();if(route==='world'&&!cloudLoading&&!needsStarter())window.HorselandiaWorld.attach({horses:worldHorses(),preferredHorse:selected,storageKey:Cloud?.active?Cloud.user.id:'guest',onBarnCare:(id,action)=>care(id,action,{silent:true}),intent:worldIntent});worldIntent=null;document.title=`${({home:'Home',stable:'Your stable',profile:horse(selected).name,community:'Community',trail:'Trail ride',world:'3D world',offline:'Install & offline',account:'Your account'})[route]} · Trottville`;if(route==='home'&&!cloudLoading&&!needsStarter()){homeAttach();TR?.maybeStreak?.();}if(needsStarter())TR.mountStarter();paintBell();TR?.Coins.paintChip();dispatchEvent(new Event('trottville:rendered'));}
// Home stage 2 (home-panels.js): the Stable panel draws this page over the stall; game cards can still send you out.
