function commentModal(id){const p=allPosts().find(p=>p.id===id);if(!p)return;const list=[...(Array.isArray(p.comments)?p.comments:[]),...(Array.isArray(state.comments[id])?state.comments[id]:[])];openModal('A little conversation',`<p class="modal-p">${esc(p.title||p.text.slice(0,70))}</p><ul class="comment-list">${list.map(c=>`<li><b>${esc(c.name)}</b>${esc(c.text)}</li>`).join('')||'<li>Be the first to leave a kind word.</li>'}</ul><form id="comment-form" data-post="${esc(id)}"><div class="form-row"><label for="comment">Your comment</label><textarea id="comment" name="comment" required maxlength="600" placeholder="Leave a little kindness…"></textarea></div><p class="small">${Cloud?.active?'Saved as private notes in your account.':'Saved to this device only.'}</p><div class="form-actions"><button type="submit" class="primary">Add comment</button></div></form>`);}
function addJournal(id,text,points){state.journal.unshift({horse:id,text,points,day:day()});state.journal=state.journal.slice(0,150);}
function care(id,action,options={}){if(ranchMode()){ranchCare(id,{bond:'pet',groom:'groom',feed:'game'}[action]||'game');return;}if(!['feed','groom','bond'].includes(action)||cared(id,action))return;const h=horse(id);state.care[careKey(id,action)]=true;state.points+=10;h.bond=Math.min(100,h.bond+3);h.happiness=Math.min(100,h.happiness+(action==='bond'?12:7));if(action==='feed')h.energy=Math.min(100,h.energy+15);addJournal(id,({feed:'A favorite treat, happily accepted.',groom:'A little brushing. A lovely new shine.',bond:'A quiet moment together.'})[action],10);save({action,horseId:id,day:day()});
  // Care pays Trotties (note #12): queued until you press Collect. The old points still sync for the cloud save.
  const careName={feed:'Fed',groom:'Brushed',bond:'Petted'}[action];TR?.Coins.queueCoins({from:`${careName} ${h.name}`,coins:10,lines:[`${careName} ${h.name} · 10 🪙`]});
  if(!options.silent)render();toast(TR?`${h.name} loved that. +10 Trotties to collect!`:`${h.name} loved that. +10 points!`);}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.route){go(b.dataset.route);return;}if(b.dataset.horse){go('horse/'+b.dataset.horse);return;}if(b.dataset.tab){feedTab=b.dataset.tab;render();return;}if(b.dataset.platform){platform=b.dataset.platform;render();return;}if(b.dataset.choice!==undefined&&trailSession&&trailSession.choice===null){trailSession.choice=Number(b.dataset.choice);render();return;}const a=b.dataset.action,id=b.dataset.id;if(!a)return;if(a==='exit-world'){history.replaceState(null,'','#'+worldReturn);navigate(worldReturn);return;}
if(Cloud?.active&&!Cloud.ready&&!['account','google-login','sign-out','refresh-cloud','close-modal'].includes(a)){toast('Open Your account to finish loading your cloud stable.');go('account');return;}
if(['google-login','sign-out','refresh-cloud','resolve-local','resolve-cloud'].includes(a)){await accountAction(a);return;}
if(a==='account'){go('account');return;}
if(a==='close-modal'){$('#modal').close();return;}
if(a==='about')openModal('Welcome back to that feeling.',`<div class="modal-p"><p>Trottville is a private working concept for a revived horse community: a place to care for a virtual herd, reconnect, and share the little things.</p><p>You’re trying a prototype with sample community members. ${progressNote()} Your community updates remain private notes; other players do not see them.</p><p>It uses an original temporary name and new imagery. It is not an official Horseland service or an announcement of a revival.</p><p><b>Try this:</b> rename a horse, finish three care tasks, take a trail ride, and install the app. Then visit the stable offline.</p></div><button class="primary full" data-action="close-modal">Make yourself at home</button>`);
if(a==='install'){go('offline');}
if(a==='native-install'){if(matchMedia('(display-mode: standalone)').matches){toast('You’re already using Trottville as an app.');}else if(deferredInstall){await deferredInstall.prompt();const choice=await deferredInstall.userChoice;deferredInstall=null;toast(choice.outcome==='accepted'?'Trottville is being added to your apps.':'You can install any time from your browser menu.');render();}else toast(platform==='ios'?'In Safari, tap Share → Add to Home Screen.':'Use your browser menu → Install app or Add to home screen.');}
if(a==='compose')openModal('A moment from your stable.',`<form id="post-form"><div class="form-row"><label for="post-text">What would you like to share?</label><textarea name="text" id="post-text" required maxlength="1200" placeholder="A small win, a favorite memory, or just a hello…"></textarea></div><div class="form-row"><label for="post-photo">Add a horse photo</label><select id="post-photo" name="photo"><option value="">Just my words</option>${state.horses.map(h=>`<option value="${h.image}">${esc(h.name)}</option>`).join('')}</select></div><p class="small">${Cloud?.active?'Your update syncs privately to your account.':'This prototype saves your update on this device.'}</p><div class="form-actions"><button type="button" class="secondary" data-action="close-modal">Cancel</button><button type="submit" class="primary">Share update</button></div></form>`);
if(a==='like'){state.liked.includes(id)?state.liked=state.liked.filter(x=>x!==id):state.liked.push(id);save();render();}
if(a==='bookmark'){state.saved.includes(id)?state.saved=state.saved.filter(x=>x!==id):state.saved.push(id);save();render();toast(state.saved.includes(id)?'Saved. Find it in the Saved tab.':'Removed from your saved moments.');}
if(a==='comments')commentModal(id);
if(a==='club'){state.clubs.includes(id)?state.clubs=state.clubs.filter(x=>x!==id):state.clubs.push(id);save();render();toast(state.clubs.includes(id)?'Joined this sample circle in your private notes.':'You left this sample circle.');}
if(a==='rsvp'){state.joined=!state.joined;save();render();toast(state.joined?'RSVP saved in your private notes. This is a sample event.':'RSVP removed.');}
if(a==='rename'){const h=horse(id);openModal('A name that feels right.',`<form id="rename-form" data-horse="${id}"><div class="form-row"><label for="horse-name">Horse name</label><input name="name" id="horse-name" value="${esc(h.name)}" maxlength="28" required></div><p class="small">Up to 28 characters. ${progressNote()}</p><div class="form-actions"><button type="button" class="secondary" data-action="close-modal">Cancel</button><button class="primary" type="submit">Save name</button></div></form>`);}
if(a==='care')care(id,b.dataset.care);
if(a==='start-trail'){selected=$('#trail-horse').value;trailSession={step:0,choice:null,finished:false,rewarded:false};render();}
if(a==='next-trail'&&trailSession){if(trailSession.step<2){trailSession.step++;trailSession.choice=null;}else{const k=`${day()}:${selected}`;trailSession.finished=true;if(!state.rides[k]){state.rides[k]=true;state.points+=30;const h=horse(selected);h.bond=Math.min(100,h.bond+8);h.energy=Math.max(0,h.energy-10);h.happiness=Math.min(100,h.happiness+10);addJournal(selected,'An autumn ride and a closer bond.',30);trailSession.rewarded=true;save({action:'ride',horseId:selected,day:day()});TR?.Coins.queueCoins({from:`Trail ride with ${h.name}`,coins:30,lines:[`Trail ride with ${h.name} · 30 🪙`]});}}render();}
if(a==='ride-again'){trailSession=null;render();}
if(a==='share-ride'){const p={id:'local-'+Date.now(),local:true,name:playerName(),initials:playerInitials(),time:'Just now',tag:'TRAIL MEMORIES',title:'The scenic route was worth it.',text:`A quiet autumn ride with ${horse(selected).name}. Three little moments, one closer bond. Sometimes this is all you need.`,image:horse(selected).image,likes:0,comments:[]};state.posts.unshift(p);state.posts=state.posts.slice(0,100);save();feedTab='mine';go('community');toast('Trail memory added to your private updates.');}
if(a==='verify-cache')await verifyCache(true);
if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='meadowgate-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your prototype progress has been exported.');}
});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,data=new FormData(f);
if(f.id==='supabase-setup-form'){try{await Cloud.configure(String(data.get('url')),String(data.get('key')));}catch(error){$('#setup-error').textContent=error.message;}return;}
if(Cloud?.active&&!Cloud.ready){toast('Please wait for your cloud stable.');return;}
if(f.id==='rename-form'){const name=String(data.get('name')).trim();if(!name){$('#horse-name').setCustomValidity('Please enter a name.');$('#horse-name').reportValidity();return;}{const bad=TR?.horseNameProblem?.(name);if(bad){$('#horse-name').setCustomValidity(bad);$('#horse-name').reportValidity();$('#horse-name').addEventListener('input',e=>e.target.setCustomValidity(''),{once:true});return;}}horse(f.dataset.horse).name=name;if(ranchMode())TR.set(TR.get(),{quiet:true});save({action:'rename',horseId:f.dataset.horse,value:name});$('#modal').close();render();toast('A lovely name. Saved to your stable.');}
if(f.id==='post-form'){const text=String(data.get('text')).trim();if(!text)return;state.posts.unshift({id:'local-'+Date.now(),local:true,name:playerName(),initials:playerInitials(),time:'Just now',tag:'YOUR UPDATE',text,image:String(data.get('photo')),likes:0,comments:[]});state.posts=state.posts.slice(0,100);save();feedTab='mine';$('#modal').close();render();toast(Cloud?.active?'Your update is queued for private account sync.':'Your update is saved on this device.');}
if(f.id==='comment-form'){const text=String(data.get('comment')).trim();if(!text)return;const id=f.dataset.post;(state.comments[id]||=[]).push({name:playerName()+(Cloud?.active?' · Private notes':' · This device'),text});save();$('#modal').close();render();commentModal(id);toast(Cloud?.active?'Your note is queued for private account sync.':'Your comment is saved on this device.');}
});
document.addEventListener('input',e=>{if(e.target.id==='horse-name')e.target.setCustomValidity('');if(e.target.id==='search'){query=e.target.value;$('#posts').innerHTML=posts();}});
document.addEventListener('change',e=>{if(e.target.id==='offline-preview'){offlinePreview=e.target.checked;connection();toast(offlinePreview?'Offline preview on. Explore your stable and trail ride.':'Offline preview off.');}if(e.target.id==='trail-horse'){selected=e.target.value;render();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
window.addEventListener('online',connection);window.addEventListener('offline',connection);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;if(route==='offline')render();});window.addEventListener('appinstalled',()=>{deferredInstall=null;toast('Welcome home. Trottville is installed.');if(route==='offline')render();});
async function verifyCache(showToast=false){if(!('serviceWorker'in navigator)){cacheStatus='Offline caching is unavailable in this browser.';if(route==='offline')render();return;}try{const reg=await navigator.serviceWorker.ready;const worker=reg.active;if(!worker)throw Error('Service worker not active');const result=await new Promise((resolve,reject)=>{const channel=new MessageChannel();const timer=setTimeout(()=>reject(Error('Cache check timed out')),7000);channel.port1.onmessage=e=>{clearTimeout(timer);resolve(e.data);};worker.postMessage({type:'VERIFY_CACHE'},[channel.port2]);});cacheReady=result.ok;cacheStatus=result.ok?`Offline ready · ${result.count} core files verified`:'Offline files are still preparing. Reconnect and reload.';if(route==='offline')render();if(showToast)toast(cacheStatus);}catch{cacheStatus='Offline setup needs a connection. Please reload and try again.';if(route==='offline')render();if(showToast)toast(cacheStatus);}}
if('serviceWorker'in navigator){navigator.serviceWorker.register('sw.js',{scope:'./',updateViaCache:'none'}).then(reg=>{reg.update().catch(()=>{});return verifyCache();}).catch(()=>{cacheStatus='Offline caching is unavailable here. Try the deployed app in your browser.';if(route==='offline')render();});}
ranchReady.finally(()=>{TrottStart.mark('ranch');booted=true;document.body.classList.add('booted');navigate(location.hash.slice(1)||'world');});
// ---- Start screen (note #46, 2026-11-15) ----
// The page opens on #start (index.html): a loading bar that fills on real events (page, fonts, ranch, account check),
// then Play / Sign in to save. Nobody is ever forced to sign in (Yoshi). Signed-in players and guests who already
// chose skip the choices; returning guests get a small "Save my horse" pill once a session.
var TrottStart=window.TrottStart=(()=>{const el=$('#start'),KEY='trottville-start-choice';
  const got={page:1},need=['page','fonts','ranch','account'],say={fonts:'Painting the meadow…',ranch:'Waking up your horses…',account:'Checking your saddlebag…'};
  let finished=!el;
  const store={get(k){try{return localStorage.getItem(k);}catch{return null;}},set(k,v){try{localStorage.setItem(k,v);}catch{}}};
  function paint(k){if(!el)return;const n=need.filter(x=>got[x]).length,p=Math.round(n/need.length*100);el.querySelector('.start-bar i').style.width=p+'%';el.querySelector('.start-bar').setAttribute('aria-valuenow',p);if(say[k])el.querySelector('.start-step').textContent=say[k];if(n===need.length)ready();}
  function mark(k){if(got[k]||finished)return;got[k]=1;paint(k);}
  function leave(){if(finished)return;finished=true;el.classList.add('gone');window.dispatchEvent(new Event('trottstart:done'));const end=()=>{el.hidden=true;};el.addEventListener('transitionend',end,{once:true});if(matchMedia('(prefers-reduced-motion: reduce)').matches)end();}
  function ready(){el.classList.remove('start-loading');if(window.MeadowCloud?.active){leave();return;}
    if(store.get(KEY)){leave();guestPill();return;}
    el.querySelector('.start-load').hidden=true;el.querySelector('.start-choices').hidden=false;el.querySelector('.start-play').focus({preventScroll:true});}
  function guestPill(){try{if(sessionStorage.getItem('trottville-guest-pill'))return;sessionStorage.setItem('trottville-guest-pill','1');}catch{}
    if(window.MeadowCloud?.active||document.querySelector('.guest-pill'))return;
    const p=document.createElement('div');p.className='guest-pill';p.setAttribute('role','status');
    p.innerHTML='<b>🐴 Playing as a guest</b><button type="button" class="gp-save">Save my horse</button><button type="button" class="gp-x" aria-label="Close">×</button>';
    p.querySelector('.gp-save').onclick=()=>{p.remove();location.hash='#account';};p.querySelector('.gp-x').onclick=()=>p.remove();document.body.append(p);
    // 2026-11-15 playtest: it sat on the coin counter/bell (taps went to sign-in). Now low on the screen, and it bows out by itself.
    setTimeout(()=>{p.classList.add('gp-out');setTimeout(()=>p.remove(),600);},12000);}
  if(el){el.classList.add('start-loading');
    el.addEventListener('click',e=>{const b=e.target.closest('[data-start]');if(!b)return;const k=b.dataset.start;
      if(k==='play'){store.set(KEY,'guest');leave();}
      else if(k==='signin'){store.set(KEY,'signin');leave();location.hash='#account';}
      else if(k==='info'){const info=el.querySelector('.start-info'),open=info.hidden;info.hidden=!open;el.querySelector('.start-choices').hidden=open;b.setAttribute('aria-expanded',String(open));if(open)info.querySelector('h2').scrollIntoView({block:'nearest'});}});
    (document.fonts?.ready||Promise.resolve()).then(()=>mark('fonts'),()=>mark('fonts'));
    const checkAccount=()=>{const c=window.MeadowCloud;if(!c||c.status!=='connecting'||!navigator.onLine)mark('account');};
    window.addEventListener('meadow:cloud',checkAccount);window.addEventListener('offline',checkAccount);checkAccount();}
  window.addEventListener('meadow:cloud',()=>{if(window.MeadowCloud?.active)document.querySelector('.guest-pill')?.remove();});
  return {mark,leave,guestPill,get open(){return !finished;}};})();

window.addEventListener('meadow:cloud',event=>{
  const incoming=event.detail.state;
  if(route==='world'&&!incoming?.guest&&!incoming?.loading){if(incoming?.horses){state=incoming;cloudLoading=false;}return;}
  if(incoming?.guest){$('#modal').close();try{state=JSON.parse(localStorage.getItem(KEY))||seed();}catch{state=seed();}cloudLoading=false;trailSession=null;activeCloudUserId=null;}
  else if(incoming?.loading)cloudLoading=true;
  else if(incoming?.horses){state=incoming;cloudLoading=false;if(activeCloudUserId!==Cloud.user?.id){trailSession=null;$('#modal').close();}activeCloudUserId=Cloud.user?.id;}
  if(Cloud?.active&&!Cloud.ready&&Cloud.status==='error'){cloudLoading=false;route='account';}
  if(route==='account')cloudLoading=false;
  render();
});

function cloudStatusHTML(){
  if(!Cloud?.active)return '';
  const status=Cloud.status;
  return `<div class="cloud-status ${status==='synced'?'saved':''}" role="status"><span>${icon(status==='synced'?'check':'clock')} ${esc(Cloud.message)}${Cloud.queueCount?' · '+Cloud.queueCount+' pending':''}</span><button class="text-button" data-route="account">Account ↗</button></div>`;
}
function account(){
  const configured=Cloud?.configured, signedIn=Cloud?.active;
  return `<a href="#world" class="acct-back">← Back to the game</a><section class="page-title"><div class="eyebrow">ONE ACCOUNT. YOUR OWN LITTLE WORLD.</div><h1>Your account</h1><p>A stable that can follow you from your phone to your computer.</p></section><div class="offline-grid"><section class="card account-card"><div class="account-emblem">${icon('stable')}</div><h2>${signedIn?'Welcome, '+esc(playerName())+'.':'Bring your stable along.'}</h2><p style="margin-top:12px">${signedIn?'Your horses, names, points, and private notes belong to this account.':'Signing in opens a separate stable, saved to Supabase. You can keep exploring the device-only demo while sign-in setup is completed.'}</p>${signedIn?`<div class="account-identity"><span class="avatar">${esc(playerInitials())}</span><div><b>${esc(Cloud.user.user_metadata?.full_name||playerName())}</b><small>${esc(Cloud.user.email||'Google account')}</small></div></div><div class="status-box"><b>${Cloud.status==='synced'?'Saved to your account':Cloud.status==='conflict'?'Choose your private notes':'Your progress status'}</b><small>${esc(Cloud.message)}</small>${Cloud.queueCount?`<small>${Cloud.queueCount} action${Cloud.queueCount===1?'':'s'} waiting to sync.</small>`:''}</div>${Cloud.status==='conflict'?'<div class="account-button-row"><button class="primary" data-action="resolve-local">Keep this device’s notes</button><button class="secondary" data-action="resolve-cloud">Use cloud notes</button></div><p class="small">Horse rewards are always reconciled by the server. A copy of your device notes is kept locally.</p>':`<button class="primary full" data-action="refresh-cloud" ${Cloud.busy?'disabled':''}>${icon('wifi')} Sync & refresh progress</button>`}<button class="secondary full" style="margin-top:10px" data-action="sign-out">Sign out on this device</button><p class="local-label">Pending changes stay associated with this account on this browser. Sign back into the same account to send them.</p>`:`<button class="google-button" data-action="google-login" ${configured&&Cloud.googleEnabled?'':'disabled'}><svg viewBox="0 0 24 24" aria-hidden="true" style="fill:currentColor;stroke:none"><path d="M21.6 12.2c0-.7-.1-1.4-.2-2.1H12v4h5.4a4.6 4.6 0 0 1-2 3v2.5h3.3c1.9-1.8 2.9-4.3 2.9-7.4ZM12 22c2.7 0 5-.9 6.7-2.4l-3.3-2.5c-.9.6-2.1 1-3.4 1-2.6 0-4.8-1.7-5.6-4H3v2.6A10 10 0 0 0 12 22ZM6.4 14.1a6 6 0 0 1 0-4.2V7.3H3a10 10 0 0 0 0 9.4ZM12 5.9c1.5 0 2.8.5 3.8 1.5l2.8-2.8A9.4 9.4 0 0 0 12 2a10 10 0 0 0-9 5.3l3.4 2.6c.8-2.3 3-4 5.6-4Z"/></svg>Continue with Google</button>${window.HorselandiaAuth?.googleStatusMarkup()||''}<details class="email-login-option"><summary>Or use an email playtest account</summary>${window.HorselandiaAuth?.markup()||''}</details><div class="status-box"><b>${configured?'Supabase project connected':'Game account setup is needed'}</b><small>${esc(Cloud?.message||'Supabase is not connected.')}</small></div><button class="secondary full" data-route="stable">Explore the device-only demo</button><p class="local-label">Signing in starts or restores your account stable. Device-only demo points are kept separate.</p>`}</section><section><div class="card"><h3 style="font-family:var(--serif);font-size:22px;margin-bottom:15px">What travels with you</h3><ul class="offline-list"><li>Horse names & accelerated age <span>Account saved</span></li><li>Daily care, bond & earned points <span>Server checked</span></li><li>Trail rewards & journal <span>Account saved</span></li><li>Your demo updates & bookmarks <span>Private notes</span></li></ul><p class="small" style="margin-top:16px">You can visit a previously opened stable offline. Queued rewards are verified on reconnect and expire when the UTC reward day changes. Other players’ live posts are not part of this prototype.</p></div><div class="card"><h3 style="font-family:var(--serif);font-size:22px;margin-bottom:10px">Private by design</h3><p class="small">The private Sites gate still controls who can open the prototype. Google sign-in identifies the player inside it. Each signed-in player can read only their own saved stable.</p></div></section></div>${ownerSetupVisible()?`<details class="card setup-details" ${configured?'':'open'}><summary>Owner setup · Supabase & Google</summary><div class="notice" style="margin-top:18px">${icon('leaf')}<div>${configured?'The backend is connected. Finish a sign-in provider and grant your friend private-site access to test a riding room. The Google client secret belongs only in Supabase.':'Connect Supabase in this conversation, or complete these settings yourself. The Google client secret belongs only in Supabase.'}</div></div>${window.HorselandiaAuth?.setupMarkup()||''}${!configured?`<ol class="guide-steps">${configured&&Cloud.config?.url===window.MEADOWGATE_SUPABASE?.url?'<li><strong>Your project is connected</strong>The dedicated Echowing playtest project already has the stable, private backgrounds, adventure progress, chat and room tables installed.</li>':'<li><strong>Create a free Supabase project</strong>Use a dedicated project and run <a href="setup/meadowgate.sql" download="horselandia-setup.sql">the prepared stable setup ↗</a>. Friend rooms also need <a href="setup/world-rooms.sql" download="horselandia-rooms.sql">the room setup ↗</a>.</li>'}<li><strong>Configure Google sign-in</strong>In Google Cloud, create an OAuth web client. Add this origin: <code>${esc(location.origin)}</code>. Add the exact Supabase callback URL from Authentication → Sign In / Providers → Google as an authorized redirect URI.</li><li><strong>Enable Google in Supabase</strong>Enter the Google client ID and client secret in the Google provider settings. Keep the Google OAuth app in Testing for this playtest, with only basic identity permissions.</li><li><strong>Set the return address</strong>In Supabase Authentication → URL Configuration, set both the Site URL and an allowed Redirect URL to <code>${esc(location.origin)}/</code>. The app uses this same root URL as its PKCE callback.</li><li><strong>Connect this browser</strong>Enter the project URL and browser-safe publishable key below. After connection, try Continue with Google. A deployed default can be set after the project is connected in this conversation.</li></ol>`:''}<form id="supabase-setup-form"><div class="form-row"><label for="supabase-url">Supabase project URL</label><input id="supabase-url" name="url" type="url" required autocomplete="off" placeholder="https://your-project.supabase.co" value="${esc(Cloud?.config?.url||'')}"></div><div class="form-row"><label for="supabase-key">Publishable key · browser-safe</label><input id="supabase-key" name="key" required autocomplete="off" spellcheck="false" placeholder="sb_publishable_…"><p class="small" style="margin-top:6px">Use the publishable or legacy anon key. Never enter a service-role key, secret key, Google client secret, or database password here.</p></div><p id="setup-error" class="error-text" role="alert"></p><button class="primary" type="submit">Save project connection</button></form></details>`:''}`;
}
async function accountAction(action){
  try{
    if(action==='google-login')await Cloud.signIn();
    if(action==='refresh-cloud'){if(Cloud.busy)return;await Cloud.refresh();}
    if(action==='sign-out'){
      if(Cloud.queueCount){openModal('Keep your unsent progress.',`<p class="modal-p">You have ${Cloud.queueCount} action(s) waiting to sync. They’ll stay saved on this browser for this Google account. Sign in to the same account later to send them.</p><div class="form-actions"><button class="secondary" data-action="close-modal">Stay signed in</button><button class="primary" id="confirm-signout">Sign out & keep pending</button></div>`);$('#confirm-signout').addEventListener('click',async()=>{try{await Cloud.signOut();$('#modal').close();}catch(error){toast(error.message);}});return;}
      await Cloud.signOut();
    }
    if(action==='resolve-local')await Cloud.resolveConflict(true);
    if(action==='resolve-cloud')await Cloud.resolveConflict(false);
  }catch(error){toast(error.message?.includes('MG_')?'Cloud setup needs attention. Open Your account for details.':error.message||'Please try again.');}
  render();
}
